steps.code:
res_a = primitives.call(
    name="inspect_robowits_scene_or_tool", query="page A with eyelets"
)
res_b = primitives.call(
    name="inspect_robowits_scene_or_tool", query="page B with eyelets"
)
res_bar = primitives.call(
    name="inspect_robowits_scene_or_tool", query="stabilizing bar"
)
for name, r in [("A", res_a), ("B", res_b), ("bar", res_bar)]:
    if r.ok:
        print(name, r.output.get("selected"))

res_state = primitives.call(
    name="observe_robowits_state",
    names=["page A with eyelets", "page B with eyelets", "stabilizing bar"],
)
if res_state.ok:
    print("state ee:", res_state.output.get("ee_state"))
    print("evidence_handles:", res_state.output.get("evidence_handles"))

res_ev = primitives.call(
    name="inspect_robowits_scene_evidence", query="standing hinge structure"
)
if res_ev.ok:
    for k, v in res_ev.output.items():
        if k == "objects" or k == "object_poses":
            for obj_k, obj_v in v.items():
                print(obj_k, list(obj_v.keys()))
                for fk, fv in obj_v.items():
                    if fk != "convex_hull_2d":
                        print("  ", fk, ":", fv)
        else:
            print(k, ":", v)

res_contact = primitives.call(
    name="inspect_robowits_contact_stability",
    names=[
        "page A with eyelets",
        "page B with eyelets",
        "stabilizing bar",
        "table",
    ],
)
if res_contact.ok:
    print("contact:", res_contact.output)

for name, obj in res_poses.output["object_poses"].items():
    print(name)
    for k, v in obj.items():
        if k == "convex_hull_2d":
            print("  hull len:", len(v), "pts:", v[:6])
        else:
            print(" ", k, ":", v)

res_loc_a = primitives.call(
    name="locate_robowits_entity", entity_name="page A with eyelets"
)
res_loc_b = primitives.call(
    name="locate_robowits_entity", entity_name="page B with eyelets"
)
res_loc_bar = primitives.call(
    name="locate_robowits_entity", entity_name="stabilizing bar"
)
for n, r in [("loc_a", res_loc_a), ("loc_b", res_loc_b), ("loc_bar", res_loc_bar)]:
    print(n, r.ok, r.output)
